import{_ as a,c as n,o as t,ag as i}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Retained algorithm exercise requirements","description":"","frontmatter":{},"headers":[],"relativePath":"practice/cs-foundations/retained-exercises.md","filePath":"practice/cs-foundations/retained-exercises.md"}'),r={name:"practice/cs-foundations/retained-exercises.md"};function s(o,e,c,d,l,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="retained-algorithm-exercise-requirements" tabindex="-1">Retained algorithm exercise requirements <a class="header-anchor" href="#retained-algorithm-exercise-requirements" aria-label="Permalink to “Retained algorithm exercise requirements”">​</a></h1><p><strong>Learner status: still required.</strong> These original requirements are preserved from the Big O and quicksort pages. The <a href="./">sequenced specifications</a> give them smaller checkpoints; they are not additional unrelated projects.</p><p><strong>Exercise acceptance:</strong> compare q repeated linear membership scans with one reusable Set over the same immutable dataset. Count construction/lookup operations before timing; vary n/q/hit rate and include memory. Verify identical answers, including absent values and the chosen equality semantics. Benchmark in a warmed target runtime with repeated samples and report variance rather than a single tiny duration. For a mutable dataset specify when the index updates or rebuilds. Explain a case where the simpler scan wins and a case where index construction amortizes. Profiling and learner evidence remain required.</p><p><strong>Acceptance:</strong> execute those exact fixtures plus singleton/self-loop/disconnected/unknown-start/missing-neighbor/duplicate-edge/budget cases. Cross-check BFS distances on small generated graphs against an independent all-pairs distance reference, and DFS reachable sets against BFS; do not just mirror the implementation in tests. Assert graph/tree inputs are unchanged, null tree gives[], skewed trees terminate and cycles/shared-child/oversize trees reject. Count queue insertions/edge examinations before timing. Explain which memory is input, validation, frontier and returned result; a tiny benchmark does not prove a bound. Learner implementation/performance measurements remain required.</p><p><strong>Exercise acceptance:</strong> instrument the exact example&#39;s comparison count, maximum recursion depth and allocated array slots without claiming those are measured heap bytes. Check empty/singleton, sorted/reversed, duplicates and random finite-number inputs against a numeric native sort; verify input preservation. For n sorted/equal elements show n(n−1)/2 comparisons and depth proportional to n using small safe n. Compare a balanced fixture and explain peak versus cumulative storage. Add a three-way/in-place variant only as an explicitly separate exercise; retain correctness and operation-count evidence before timing. Large worst-case recursion is intentionally not a recommended production stress test.</p><h2 id="existing-collection-exercise" tabindex="-1"><span class="hub-section-number">1 </span>Existing collection exercise <a class="header-anchor" href="#existing-collection-exercise" aria-label="Permalink to “1 Existing collection exercise”">​</a></h2><p><strong>Exercise:</strong> implement a small bounded Map cache with a documented FIFO or LRU policy. Acceptance: distinguish missing from stored undefined; show object identity and NaN/zero cases; verify object key order; reject unsupported serialized keys; enforce an entry limit; explain why no deterministic test can demand a WeakMap key be collected at a particular time. Verify WeakMap symbol support on each runtime in your compatibility matrix.</p><h2 id="existing-memoization-exercise" tabindex="-1"><span class="hub-section-number">2 </span>Existing memoization exercise <a class="header-anchor" href="#existing-memoization-exercise" aria-label="Permalink to “2 Existing memoization exercise”">​</a></h2><p><strong>Exercise acceptance:</strong> run the exact synchronous wrapper against un-memoized results. Count calls for every falsy value; distinguish numeric/string/array/object/argument-count keys and two different receivers; verify NaN hits, +0/−0 separation, exception retry, LRU hit promotion/eviction and clear. Demonstrate stale output after mutating an object, then fix the ownership/invalidation contract. Verify fibMemo0/1/40 and invalid bounds without running huge recursion. Compare hit/miss rate and retained data against the cost of recalculation. Async cache design and learner implementation remain separate practice.</p><h2 id="existing-execution-and-binding-exercise" tabindex="-1"><span class="hub-section-number">3 </span>Existing execution and binding exercise <a class="header-anchor" href="#existing-execution-and-binding-exercise" aria-label="Permalink to “3 Existing execution and binding exercise”">​</a></h2><p><strong>Exercise acceptance:</strong> run those results under strict function code/ESM, create two independent counters and explain binding versus object identity and captured lifetime. Compare classic-script, CommonJS-wrapper and ESM top-level this using separate files rather than assuming a REPL result applies to all. Use a heap snapshot/retaining path for a real leak; do not assert a GC schedule or physical stack placement from console output. Learner debugging remains required.</p>',11)])])}const h=a(r,[["render",s]]);export{u as __pageData,h as default};
